import CryptoKit
import Foundation
import Testing
@testable import Kudos

/// T-567 P1: the fixture generator is deterministic, hits its size target on each axis, and writes a document
/// today's decoder accepts. Small sizes only; the large sizes are generated by the opt-in baseline harness.
extension PersistenceGateSuites {
@MainActor
@Suite(.serialized)
struct ManifestFixtureGeneratorTests {
    private func defaults() throws -> UserDefaults {
        let name = "ManifestFixtureGeneratorTests.\(UUID().uuidString)"
        let defaults = try #require(UserDefaults(suiteName: name))
        defaults.removePersistentDomain(forName: name)
        return defaults
    }

    private func sha(_ url: URL) throws -> String {
        SHA256.hash(data: try Data(contentsOf: url)).map { String(format: "%02x", $0) }.joined()
    }

    @Test(arguments: ManifestScaleAxis.allCases)
    func smallFixtureIsDeterministicOnTargetAndDecodes(axis: ManifestScaleAxis) throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("t567-gen-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }
        let d = try defaults()
        let spec = try ManifestFixtureGenerator.calibrated(axis: axis, mib: 1)
        let a = try ManifestFixtureGenerator.write(spec, to: dir.appendingPathComponent("a.json"), defaults: d)
        let b = try ManifestFixtureGenerator.write(spec, to: dir.appendingPathComponent("b.json"), defaults: d)
        let da = try Data(contentsOf: a.manifestURL), db = try Data(contentsOf: b.manifestURL)
        if da != db, let i = zip(da, db).enumerated().first(where: { $0.element.0 != $0.element.1 })?.offset {
            let lo = max(0, i - 80)
            Issue.record("diff at \(i) of \(da.count)/\(db.count): \(String(decoding: da[lo ..< min(da.count, i + 80)], as: UTF8.self)) VS \(String(decoding: db[lo ..< min(db.count, i + 80)], as: UTF8.self))")
        }
        #expect(try sha(a.manifestURL) == sha(b.manifestURL))
        let target = Double(spec.targetBytes)
        #expect(abs(Double(a.bytes) - target) / target < 0.15, "bytes \(a.bytes) target \(spec.targetBytes) \(spec)")
        let manifest = try KudosBackupContents.decodeManifest(Data(contentsOf: a.manifestURL))
        #expect(manifest.works.count == spec.works)
        #expect(manifest.readingSessions?.count == spec.sessions)
        #expect(manifest.documents?.count ?? 0 == spec.documents)
        #expect(manifest.writingRecovery?.count ?? 0 == spec.recoveryCopies)
        #expect(manifest.omittedKeys.isEmpty)
        #expect(manifest.works.filter(\.hasEPUB).count == spec.epubWorks)
    }

    @Test func archiveHoldsManifestAndDummyEPUBs() throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("t567-gen-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }
        let spec = try ManifestFixtureGenerator.calibrated(axis: .works, mib: 0.5)
        let out = try ManifestFixtureGenerator.write(spec, to: dir.appendingPathComponent("m.json"), defaults: defaults())
        let zipURL = dir.appendingPathComponent("a.kudosbackup")
        try ManifestFixtureGenerator.writeArchive(out, to: zipURL)
        let contents = try KudosBackupContents.read(from: zipURL)
        #expect(contents.manifest.works.count == spec.works)
        #expect(contents.epubData(for: out.epubWorkIDs[0]) != nil)
    }
}
}
